const c = $input.first().json;
const get = async (path) => this.helpers.httpRequest({ method: 'GET', url: `${c.directusUrl}${path}`, headers: { Authorization: `Bearer ${c.directusToken}` }, json: true, timeout: 30000 });
const types = String(c.areaTypes || 'city,road').split(',').map(t => t.trim()).filter(Boolean);
const hasBounds = a => ['bounds_min_lat','bounds_max_lat','bounds_min_lon','bounds_max_lon'].every(k => Number.isFinite(Number(a[k])));
const areas = [];
if (types.includes('city')) {
  const r = await get('/items/cities?limit=-1&fields=slug,bounds_min_lat,bounds_max_lat,bounds_min_lon,bounds_max_lon&filter[status][_eq]=published');
  for (const x of (r.data || []).filter(hasBounds).slice(0, Math.max(1, Number(c.cityLimit || 295)))) areas.push({ ...x, type: 'city', parent: null });
}
if (types.includes('road')) {
  const r = await get('/items/road_segments?limit=-1&fields=id,slug,route_code,stations_locked,bounds_min_lat,bounds_max_lat,bounds_min_lon,bounds_max_lon&filter[status][_eq]=published');
  for (const x of (r.data || []).filter(hasBounds).slice(0, Math.max(1, Number(c.segmentLimit || 400)))) areas.push({ ...x, type: 'road', parent: x.route_code || null });
}
return [{ json: { ...c, areas } }];

const result = [];
for (const input of $input.all()) {
  const x = input.json, area = x.area;
  const url = `${x.stationsApiUrl}?minLat=${area.bounds_min_lat}&maxLat=${area.bounds_max_lat}&minLon=${area.bounds_min_lon}&maxLon=${area.bounds_max_lon}`;
  try {
    const stations = await this.helpers.httpRequest({ method: 'GET', url, json: true, timeout: Number(x.requestTimeoutMs) || 15000 });
    result.push({ json: { ...x, stations, fetchStatus: 'ok' } });
  } catch (error) {
    result.push({ json: { ...x, stations: [], fetchStatus: 'failed', fetchError: error instanceof Error ? error.message : String(error) } });
  }
}
return result;

const output=[];
for(const input of $input.all()){
  const x=input.json, now=Date.now(), groups=new Map();
  const clean=v=>String(v||'').toLocaleLowerCase('ru-RU').replaceAll('\u0451','\u0435').replace(/[\u00ab\u00bb"']/g,'').replace(/,?\s*(?:\u0410\u0417\u0421|\u0437\u0430\u043f\u0440\u0430\u0432\u043e\u0447\u043d\u0430\u044f \u0441\u0442\u0430\u043d\u0446\u0438\u044f)$/iu,'').trim();
  for(const it of (Array.isArray(x.stations)?x.stations:[])){
    const s=it?.station;
    if(!s||!Array.isArray(it.prices))continue;
    const name=s.brand||String(s.name||'').split(',')[0]||'\u0410\u0417\u0421';
    const slug=clean(name).replace(/[^a-z0-9\u0430-\u044f]+/giu,'-');
    const g=groups.get(slug)||{slug,name,count:0,tz:Number(s.timezone_offset)||3,p:new Map()};
    g.count++;
    for(const q of it.prices){
      const v=Number(q.price), u=Date.parse(q.updated_at);
      if(v>0&&Number.isFinite(u)&&now-u<=604800000){
        const a=g.p.get(q.fuel_type)||[];
        a.push({v,u:q.updated_at});
        g.p.set(q.fuel_type,a);
      }
    }
    groups.set(slug,g);
  }
  const snapshots=[];
  for(const g of groups.values()){
    const fuels=[...g.p].map(([fuelType,a])=>({
      fuelType,
      average:Number((a.reduce((s,q)=>s+q.v,0)/a.length).toFixed(2)),
      min:Math.min(...a.map(q=>q.v)),
      max:Math.max(...a.map(q=>q.v)),
      sampleCount:a.length,
      updatedAt:a.sort((u,v)=>Date.parse(v.u)-Date.parse(u.u))[0].u
    }));
    if(!fuels.length)continue;
    const d=new Date(now+g.tz*3600000);
    d.setUTCMinutes(d.getUTCMinutes()<30?0:30,0,0);
    snapshots.push({
      area_type:x.area.type,
      area_slug:x.area.slug,
      area_parent_slug:x.area.parent||null,
      brand_slug:g.slug,
      snapshot_date:d.toISOString().slice(0,19)+'Z',
      station_count:g.count,
      source_updated_at:fuels.map(f=>f.updatedAt).sort().at(-1),
      fuel_prices:fuels
    });
  }
  output.push({json:{...x,snapshots}});
}
return output;

const output = [];
const c = $input.first().json;
const headers = { Authorization: `Bearer ${c.directusToken}`, "Content-Type": "application/json" };

const upsert = async (collection, data) => {
  if (!data || data.length === 0) return;
  for (let i = 0; i < data.length; i += 100) {
    const batch = data.slice(i, i + 100);
    const res = await this.helpers.httpRequest({
      method: "PATCH",
      url: `${c.directusUrl}/items/${collection}`,
      headers,
      body: batch,
      json: true
    });
    const updatedIds = new Set((res.data || []).map(item => String(item.id)));
    const toPost = batch.filter(item => !updatedIds.has(String(item.id)));
    if (toPost.length > 0) {
      await this.helpers.httpRequest({
        method: "POST",
        url: `${c.directusUrl}/items/${collection}`,
        headers,
        body: toPost,
        json: true
      });
    }
  }
};

for (const input of $input.all()) {
  const x = input.json;
  const areaSnapshots = [];
  const pointSnapshots = [];
  const stationUpdates = [];

  if (Array.isArray(x.snapshots)) {
    for (const s of x.snapshots) {
      areaSnapshots.push({
        id: `${s.area_type}:${s.area_slug}:${s.brand_slug}:${s.snapshot_date}`,
        station: null,
        area_type: s.area_type,
        area_slug: s.area_slug,
        area_parent_slug: s.area_parent_slug,
        brand_slug: s.brand_slug,
        snapshot_date: s.snapshot_date,
        station_count: s.station_count,
        source_updated_at: s.source_updated_at,
        fuel_prices: s.fuel_prices
      });
    }
  }

  if (Array.isArray(x.stations)) {
    const now = new Date();
    const clean = v => String(v || "").toLocaleLowerCase("ru-RU").replace(/[\u00ab\u00bb"']/g, "").trim();
    for (const it of x.stations) {
      const s = it.station;
      if (!s || s.id === undefined || s.id === null) continue;
      const stationId = String(s.id);
      const tz = Number(s.timezone_offset || 3);
      const snapshotDate = new Date(now.getTime() + tz * 3600000);
      snapshotDate.setUTCMinutes(snapshotDate.getUTCMinutes() < 30 ? 0 : 30, 0, 0);
      const snapshotDateStr = snapshotDate.toISOString().slice(0, 19) + "Z";

      const name = s.brand || String(s.name || "").split(",")[0] || "\u0410\u0417\u0421";
      const brandSlug = clean(name).replace(/[^a-z0-9\u0430-\u044f]+/giu, "-");
      const queue_level = (it.fuel_statuses || []).find(f => f.queue_level)?.queue_level || null;

      stationUpdates.push({
        id: stationId,
        name: s.name,
        brand: brandSlug,
        address: s.address,
        lat: Number(s.lat),
        lng: Number(s.lng ?? s.lon),
        fuel_assortment: s.fuel_assortment || s.fuel_types || [],
        prices: it.prices || [],
        fuel_statuses: it.fuel_statuses || [],
        last_transaction_at: it.updated_at,
        status: it.status || "open",
        closed: it.status === "closed",
        queue_level
      });

      if (Array.isArray(it.prices) && it.prices.length > 0) {
        pointSnapshots.push({
          id: `point:${stationId}:${snapshotDateStr}`,
          station: stationId,
          brand_slug: brandSlug,
          area_type: "point",
          area_slug: stationId,
          area_parent_slug: x.area?.slug || null,
          snapshot_date: snapshotDateStr,
          fuel_prices: it.prices.map(p => ({
            fuelType: p.fuel_type,
            average: Number(p.price),
            min: Number(p.price),
            max: Number(p.price),
            sampleCount: 1,
            updatedAt: p.updated_at
          })),
          station_count: 1,
          source_updated_at: it.updated_at
        });
      }
    }
  }

  try {
    // stations must exist before gas_daily rows reference them via M2O
    await upsert("stations", stationUpdates);
    await upsert("gas_daily", areaSnapshots);
    await upsert("gas_daily", pointSnapshots);
    output.push({ json: { area: x.area.slug, status: "ok", stations: stationUpdates.length, snapshots: areaSnapshots.length, points: pointSnapshots.length } });
  } catch (e) {
    output.push({ json: { area: x.area.slug, status: "error", message: e.message } });
  }
}
return output;
